mapper.select:
		/*
			AlarmMapper.selectAlarmListCount
		*/
		SELECT COUNT(ALM_SEQ)
		FROM T_ALARM_STATUS
		WHERE 1 = 1

		  AND COMPANY_CODE = #{companyCode}


		  AND ALM_DATE >= CONVERT(DATETIME, REPLACE(#{startDate}, '-', ''), 112)
          AND ALM_DATE < DATEADD(DAY, 1, CONVERT(DATETIME, REPLACE(#{endDate}, '-', ''), 112))


		  AND SVC_NAME = #{svcName}

/* AlarmMapper.selectAlarmList */ SELECT ALM_SEQ, COMPANY_CODE, SVC_NAME, PROC_NAME, TABLE_NAME, MON_TYPE, CASE WHEN MON_TYPE = 1 THEN 'DB 세션 단절' WHEN MON_TYPE = 2 THEN 'KT 세션 단절' WHEN MON_TYPE = 3 THEN 'S/W down' WHEN MON_TYPE = 4 THEN '미발송 적체' WHEN MON_TYPE = 5 THEN '결과대기 적체' ELSE '기타' END AS MON_COMMENT, ALM_TYPE, CASE WHEN ALM_TYPE = 1 THEN '발생' WHEN ALM_TYPE = 2 THEN '복구' ELSE '기타' END AS ALM_COMMENT , ISNULL(ALM_INFO, '-') AS ALM_INFO, CONVERT(char(19), ALM_DATE, 120) AS ALM_DATE FROM T_ALARM_STATUS WHERE 1 = 1
AND COMPANY_CODE = #{companyCode}
AND ALM_DATE >= CONVERT(DATETIME, REPLACE(#{startDate}, '-', ''), 112) AND ALM_DATE < DATEADD(DAY, 1, CONVERT(DATETIME, REPLACE(#{endDate}, '-', ''), 112))
AND SVC_NAME = #{svcName}
ORDER BY ALM_DATE DESC OFFSET #{skip} ROWS FETCH NEXT #{take} ROWS ONLY
